<?php
session_start();require_once '../config/database.php';require_once 'lib.php';if(!isset($_SESSION['user_id'])){header('Location: ../login.php');exit;}$railroad=ttOperationsRailroad($pdo,(int)$_SESSION['user_id']);$railroadId=(int)$railroad['id'];$sessionId=(int)($_GET['id']??$_POST['session_id']??0);$error='';
$sessionStmt=$pdo->prepare('SELECT * FROM operating_sessions WHERE id=? AND railroad_id=?');$sessionStmt->execute([$sessionId,$railroadId]);$session=$sessionStmt->fetch(PDO::FETCH_ASSOC);if(!$session){if(isset($_GET['job_id'])){header('Location: sessions.php');exit;}http_response_code(404);die('Operating session not found.');}
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{ttOperationsRequireCsrf();$action=(string)($_POST['action']??'');
  if($action==='add_assignment'){$pdo->beginTransaction();$jobId=(int)($_POST['job_template_id']??0);$stmt=$pdo->prepare('SELECT * FROM jobs WHERE id=? AND railroad_id=? AND active=1 FOR UPDATE');$stmt->execute([$jobId,$railroadId]);$job=$stmt->fetch(PDO::FETCH_ASSOC);if(!$job)throw new RuntimeException('Choose an active Job Title.');$stmt=$pdo->prepare('SELECT COALESCE(MAX(sequence_number),0)+1 FROM operation_assignments WHERE session_id=? FOR UPDATE');$stmt->execute([$sessionId]);$sequence=(int)$stmt->fetchColumn();$assignmentNumber=$session['session_number'].'-'.ttAssignmentSuffix($sequence);$patterns=ttJobTypes();$pattern=(string)($_POST['operating_pattern']??$job['job_type']);if(!isset($patterns[$pattern]))throw new RuntimeException('Invalid operating pattern.');$startMethods=['locomotives_only','coupled_selected','prepared_cut','manual','auto_build','inherit'];$startMethod=(string)($_POST['start_method']??'locomotives_only');if(!in_array($startMethod,$startMethods,true))throw new RuntimeException('Invalid start method.');$baseId=(int)($_POST['operating_base_industry_id']??0);$predecessor=(int)($_POST['predecessor_assignment_id']??0);$status=$startMethod==='inherit'?'waiting':'draft';
   $stmt=$pdo->prepare('INSERT INTO operation_assignments(railroad_id,session_id,job_template_id,assignment_number,sequence_number,title_snapshot,type_snapshot,description_snapshot,operating_pattern,status,operating_base_industry_id,starting_track,start_method,prepared_cut_id,requested_car_count,difficulty,crew_name,predecessor_assignment_id,dependency_mode,end_plan,end_industry_id,end_track,notes) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)');
   $stmt->execute([$railroadId,$sessionId,$jobId,$assignmentNumber,$sequence,$job['job_name'],$job['job_type'],$job['description'],$pattern,$status,$baseId?:null,substr(trim((string)($_POST['starting_track']??'')),0,120),$startMethod,($cut=(int)($_POST['prepared_cut_id']??0))?:null,max(0,min(100,(int)($_POST['requested_car_count']??10))),in_array($_POST['difficulty']??'', ['easy','medium','hard'],true)?$_POST['difficulty']:'medium',substr(trim((string)($_POST['crew_name']??'')),0,120),$predecessor?:null,$predecessor?((string)($_POST['dependency_mode']??'entire_train')):null,(string)($_POST['end_plan']??'return_origin'),($end=(int)($_POST['end_industry_id']??0))?:null,substr(trim((string)($_POST['end_track']??'')),0,120),substr(trim((string)($_POST['notes']??'')),0,5000)]);$assignmentId=(int)$pdo->lastInsertId();
   $reserved=ttReservedEquipmentIds($pdo,$railroadId,$assignmentId);$position=1;foreach(array_unique(array_map('intval',(array)($_POST['locomotive_ids']??[]))) as $equipmentId){if($equipmentId<=0)continue;if(in_array($equipmentId,$reserved,true))throw new RuntimeException('A selected locomotive is reserved by another active assignment.');$check=$pdo->prepare("SELECT id FROM equipment WHERE id=? AND railroad_id=? AND active=1 AND equipment_class='Locomotive'");$check->execute([$equipmentId,$railroadId]);if(!$check->fetchColumn())throw new RuntimeException('Invalid locomotive selection.');$ins=$pdo->prepare("INSERT INTO operation_assignment_locomotives(assignment_id,equipment_id,position,source) VALUES(?,?,?,'selected')");$ins->execute([$assignmentId,$equipmentId,$position++]);}
   if($cut){$check=$pdo->prepare("SELECT id FROM prepared_cuts WHERE id=? AND railroad_id=? AND status='ready' FOR UPDATE");$check->execute([$cut,$railroadId]);if(!$check->fetchColumn())throw new RuntimeException('Prepared cut is no longer available.');$cars=$pdo->prepare('SELECT equipment_id,position FROM prepared_cut_cars WHERE prepared_cut_id=? ORDER BY position');$cars->execute([$cut]);$ins=$pdo->prepare("INSERT INTO operation_assignment_starting_cars(assignment_id,equipment_id,position,source_type,source_id) VALUES(?,?,?,'prepared_cut',?)");foreach($cars->fetchAll(PDO::FETCH_ASSOC) as $car){if(in_array((int)$car['equipment_id'],$reserved,true))throw new RuntimeException('A prepared-cut car is reserved elsewhere.');$ins->execute([$assignmentId,(int)$car['equipment_id'],(int)$car['position'],$cut]);}$pdo->prepare("UPDATE prepared_cuts SET status='assigned' WHERE id=?")->execute([$cut]);}
   $pdo->commit();header('Location: session_edit.php?id='.$sessionId);exit;}
  if($action==='start_session'){$stmt=$pdo->prepare("UPDATE operating_sessions SET status='in_progress',started_at=COALESCE(started_at,NOW()) WHERE id=? AND railroad_id=? AND EXISTS(SELECT 1 FROM operation_assignments WHERE session_id=? AND status IN('ready','waiting'))");$stmt->execute([$sessionId,$railroadId,$sessionId]);header('Location: session_edit.php?id='.$sessionId);exit;}
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}}
$jobsStmt=$pdo->prepare('SELECT id,job_name,job_type FROM jobs WHERE railroad_id=? AND active=1 ORDER BY job_name');$jobsStmt->execute([$railroadId]);$jobs=$jobsStmt->fetchAll(PDO::FETCH_ASSOC);$industriesStmt=$pdo->prepare('SELECT id,industry_name FROM industries WHERE railroad_id=? ORDER BY industry_name');$industriesStmt->execute([$railroadId]);$industries=$industriesStmt->fetchAll(PDO::FETCH_ASSOC);$locosStmt=$pdo->prepare("SELECT id,reporting_marks,road_number,road_name,current_track FROM equipment WHERE railroad_id=? AND active=1 AND equipment_class='Locomotive' ORDER BY reporting_marks,road_number");$locosStmt->execute([$railroadId]);$locomotives=$locosStmt->fetchAll(PDO::FETCH_ASSOC);$cutsStmt=$pdo->prepare("SELECT c.*,COUNT(pc.equipment_id) car_count,i.industry_name FROM prepared_cuts c JOIN industries i ON i.id=c.current_industry_id LEFT JOIN prepared_cut_cars pc ON pc.prepared_cut_id=c.id WHERE c.railroad_id=? AND c.status='ready' GROUP BY c.id ORDER BY c.cut_number");$cutsStmt->execute([$railroadId]);$cuts=$cutsStmt->fetchAll(PDO::FETCH_ASSOC);$assignStmt=$pdo->prepare("SELECT a.*,i.industry_name base_name,COUNT(DISTINCT al.equipment_id) locomotive_count,COUNT(DISTINCT ac.equipment_id) starting_car_count,MAX(sl.id) switch_list_id,MAX(sl.revision_number) revision_number,MAX(sl.planned_move_count) planned_move_count FROM operation_assignments a LEFT JOIN industries i ON i.id=a.operating_base_industry_id LEFT JOIN operation_assignment_locomotives al ON al.assignment_id=a.id LEFT JOIN operation_assignment_starting_cars ac ON ac.assignment_id=a.id LEFT JOIN operation_switch_lists sl ON sl.assignment_id=a.id WHERE a.session_id=? AND a.railroad_id=? GROUP BY a.id ORDER BY a.sequence_number");$assignStmt->execute([$sessionId,$railroadId]);$assignments=$assignStmt->fetchAll(PDO::FETCH_ASSOC);$patterns=ttJobTypes();
?>
<?php include '../includes/header.php';?><title><?=ttHtml($session['session_number'])?> Session Builder</title><link rel="stylesheet" href="../assets/css/operations.css"></head><body><?php include '../includes/navbar.php';?><div class="tt-operations-shell"><?php include '../assets/components/sidebar.php';?><section class="tt-ops-page"><div class="d-flex flex-wrap justify-content-between gap-3 mb-4"><div><p class="tt-eyebrow">Operating Session</p><h1><?=ttHtml($session['session_number'])?><?= $session['session_name']?' — '.ttHtml($session['session_name']):''?></h1><p class="text-muted"><?=ttHtml($session['operating_date'])?> · <span class="badge tt-status-<?=ttHtml($session['status'])?>"><?=ttHtml(ucwords(str_replace('_',' ',$session['status'])))?></span></p></div><form method="post"><input type="hidden" name="csrf_token" value="<?=ttHtml(ttOperationsCsrfToken())?>"><input type="hidden" name="session_id" value="<?=$sessionId?>"><input type="hidden" name="action" value="start_session"><button class="btn btn-success" <?=$assignments?'':'disabled'?>>Start Session</button></form></div><?php if($error):?><div class="alert alert-danger"><?=ttHtml($error)?></div><?php endif;?>
