<div class="card"><div class="card-header"><h2 class="h4 mb-0">Add Another Assignment</h2></div><div class="card-body"><form method="post" class="row g-3"><input type="hidden" name="csrf_token" value="<?=ttHtml(ttOperationsCsrfToken())?>"><input type="hidden" name="session_id" value="<?=$sessionId?>"><input type="hidden" name="action" value="add_assignment"><div class="col-md-6"><label class="form-label">Job Title</label><select class="form-select" name="job_template_id" required><option value="">Choose…</option><?php foreach($jobs as $job):?><option value="<?=(int)$job['id']?>"><?=ttHtml($job['job_name'])?></option><?php endforeach;?></select></div><div class="col-md-6"><label class="form-label">Operating Pattern</label><select class="form-select" name="operating_pattern"><?php foreach($patterns as $value=>$label):?><option value="<?=ttHtml($value)?>"><?=ttHtml($label)?></option><?php endforeach;?></select></div><div class="col-md-6"><label class="form-label">Start Method</label><select class="form-select" name="start_method"><option value="locomotives_only">Locomotives only</option><option value="coupled_selected">Already coupled to selected cars</option><option value="prepared_cut">Travel light to pick up a prepared cut</option><option value="manual">Select starting cars manually</option><option value="auto_build">Auto-build from eligible yard/track cars</option><option value="inherit">Inherit from previous assignment</option></select></div><div class="col-md-6"><label class="form-label">Prepared Cut</label><select class="form-select" name="prepared_cut_id"><option value="">None</option><?php foreach($cuts as $cut):?><option value="<?=(int)$cut['id']?>"><?=ttHtml($cut['cut_number'].' — '.$cut['name'].' ('.$cut['car_count'].' cars, '.$cut['industry_name'].' / '.$cut['current_track'].')')?></option><?php endforeach;?></select></div><div class="col-md-6"><label class="form-label">Operating Base</label><select class="form-select" name="operating_base_industry_id"><option value="">Choose…</option><?php foreach($industries as $industry):?><option value="<?=(int)$industry['id']?>"><?=ttHtml($industry['industry_name'])?></option><?php endforeach;?></select></div><div class="col-md-6"><label class="form-label">Starting Track</label><input class="form-control" name="starting_track" maxlength="120"></div><div class="col-12"><label class="form-label">Locomotives</label><div class="tt-check-grid"><?php foreach($locomotives as $loco):?><label><input type="checkbox" name="locomotive_ids[]" value="<?=(int)$loco['id']?>"> <?=ttHtml(trim($loco['reporting_marks'].' '.$loco['road_number'].' '.$loco['road_name']))?></label><?php endforeach;?></div></div><div class="col-md-4"><label class="form-label">Crew</label><input class="form-control" name="crew_name" maxlength="120" placeholder="May be assigned later"></div><div class="col-md-4"><label class="form-label">Cars To Switch (maximum)</label><input class="form-control" type="number" name="requested_car_count" min="0" max="100" value="10"></div><div class="col-md-4"><label class="form-label">Difficulty</label><select class="form-select" name="difficulty"><option>easy</option><option selected>medium</option><option>hard</option></select></div><div class="col-md-6"><label class="form-label">Depends On</label><select class="form-select" name="predecessor_assignment_id"><option value="">None</option><?php foreach($assignments as $a):?><option value="<?=(int)$a['id']?>"><?=ttHtml($a['assignment_number'].' — '.$a['title_snapshot'])?></option><?php endforeach;?></select></div><div class="col-md-6"><label class="form-label">Inheritance</label><select class="form-select" name="dependency_mode"><option value="locomotives">Locomotives</option><option value="cars">Selected cars</option><option value="entire_train">Entire train</option><option value="continue">Continue directly</option></select></div><div class="col-md-6"><label class="form-label">End Plan</label><select class="form-select" name="end_plan"><option value="return_origin">Return to origin and tie down</option><option value="terminate_elsewhere">Terminate at another location</option><option value="release_cars">Release cars and retain locomotives</option><option value="release_locomotives">Release locomotives and leave train</option><option value="handoff_cars">Hand off selected cars</option><option value="handoff_train">Hand off entire train</option><option value="continue_next">Continue as next assignment</option><option value="tie_down_locomotives">Tie down locomotives</option></select></div><div class="col-md-3"><label class="form-label">End Location</label><select class="form-select" name="end_industry_id"><option value="">As planned</option><?php foreach($industries as $industry):?><option value="<?=(int)$industry['id']?>"><?=ttHtml($industry['industry_name'])?></option><?php endforeach;?></select></div><div class="col-md-3"><label class="form-label">End Track</label><input class="form-control" name="end_track" maxlength="120"></div><div class="col-12"><label class="form-label">Notes</label><textarea class="form-control" name="notes" rows="2"></textarea></div><div><button class="btn btn-primary">Add Assignment</button></div></form></div></div></section></div><?php include '../includes/footer.php';?>
